ject","properties":{"minutes":{"type":"integer","enum":[0,5,10,15],"description":"0 (off), 5, 10 or 15."}},"required":["minutes"]},"_surfaces":["text","voice"]},{"type":"function","name":"set_usable_minutes","description":"Set how many minutes a day they have for focused work, on weekdays and/or weekend days — the budget Today plans against.","parameters":{"type":"object","properties":{"weekdayMin":{"type":"integer","description":"Minutes per weekday."},"weekendMin":{"type":"integer","description":"Minutes per weekend day."}},"required":[]},"_surfaces":["text","voice"]},{"type":"function","name":"set_ritual","description":"Turn one of the assistant's recurring moments on or off: the morning plan, the evening wrap-up, the Friday review, the Sunday look-ahead.","parameters":{"type":"object","properties":{"ritual":{"type":"string","enum":["morning","evening","friday","sunday"],"description":"Which moment."},"on":{"type":"boolean","description":"true = on (default), false = off."}},"required":["ritual"]},"_surfaces":["text","voice"]},{"type":"function","name":"set_theme","description":"Switch the app's appearance: light, dark, or follow the system.","parameters":{"type":"object","properties":{"theme":{"type":"string","enum":["system","light","dark"],"description":"The theme."}},"required":["theme"]},"_surfaces":["text","voice"]},{"type":"function","name":"set_focus_defaults","description":"Change the focus-session defaults: the default length, the soft overrun grace, whether leaving asks for confirmation, and whether pausing asks why. Pass only what changes.","parameters":{"type":"object","properties":{"defaultMinutes":{"type":"integer","enum":[15,25,45],"description":"Default session length."},"overrunMinutes":{"type":"integer","enum":[0,5,10],"description":"Grace minutes after the timer ends (0 = none)."},"softExit":{"type":"boolean","description":"Ask before leaving a running session."},"pauseReasons":{"type":"boolean","description":"Ask why when pausing."}},"required":[]},"_surfaces":["text","voice"]},{"type":"function","name":"set_ambient_sound","description":"Set the background sound during focus: off, brown noise, or pink noise.","parameters":{"type":"object","properties":{"sound":{"type":"string","enum":["off","brown","pink"],"description":"The sound."}},"required":["sound"]},"_surfaces":["text","voice"]},{"type":"function","name":"save_profile_fact","description":"Remember a durable fact about the user: a person in their life, a rhythm, a constraint, a preference, or context. Use it whenever they state something worth keeping. One short third-person sentence.","parameters":{"type":"object","properties":{"category":{"type":"string","enum":["person","rhythm","constraint","preference","context"],"description":"Kind of fact."},"fact":{"type":"string","description":"One short sentence, e.g. \"Sam — partner, works night shifts\"."},"whenIso":{"type":"string","description":"YYYY-MM-DD when the fact is tied to a date (a birthday, a deadline) — the app reminds them as it approaches."}},"required":["category","fact"]},"_surfaces":["text","voice"]},{"type":"function","name":"forget_fact","description":"Forget something remembered about them. Give the fact's id if known, otherwise words from it; if several match the result lists them — ask which.","parameters":{"type":"object","properties":{"factId":{"type":"string","description":"The fact's id, if known."},"match":{"type":"string","description":"Words from the fact."}},"required":[]},"_surfaces":["text","voice"]},{"type":"function","name":"finish_interview","description":"Call once, when every get-to-know-you question from the opening has been answered or skipped — marks the intro done so it is never asked again. Only during that intro.","parameters":{"type":"object","properties":{},"required":[]},"_surfaces":["text","voice"]},{"type":"function","name":"get_insights","description":"READ how their focus is going: totals, estimate accuracy, why they pause, what is slipping. Call it before answering a how-am-I-doing question.","parameters":{"type":"object","properties":{"window":{"type":"string","enum":["week","month","all"],"description":"Period (default week)."}},"required":[]},"_surfaces":["text","voice"]},{"type":"function","name":"get_period_review","description":"READ how a past day, week or month went: what got done, focus, what slipped, vs before. Call it BEFORE answering any how-has-my-week-been / how was last week / what did I get done yesterday / how was the week of 7 September / how's this month going question — get_schedule shows only what is PLANNED, and an empty calendar never means nothing got done. Weeks run Monday to Sunday; a period that includes today is reviewed so far. Answer only from its numbers and names.","parameters":{"type":"object","properties":{"period":{"type":"string","enum":["today","yesterday","this_week","last_week","this_month","last_month","week_of","month_of","dates"],"description":"Which span: a preset; week_of / month_of = the week or month containing date; dates = from..to (at most 93 days)."},"date":{"type":"string","description":"YYYY-MM-DD in that week/month (week_of, month_of)."},"from":{"type":"string","description":"YYYY-MM-DD: first day, for period=dates."},"to":{"type":"string","description":"YYYY-MM-DD: last day, inclusive (dates; default = from)."}},"required":["period"]},"_surfaces":["text","voice"]},{"type":"function","name":"share_task","description":"Prepare sharing a task with someone in the user's trusted circle or with an email address. This only STAGES it — the user confirms on screen. Levels: view (see it), partner (work on it together), assign (hand it over). After calling it say it's ready to confirm; never say it has been shared.","parameters":{"type":"object","properties":{"taskId":{"type":"string","description":"Preferred: The task's id — from the context snapshot, get_tasks, find_tasks, or a task created this turn. Never guess an id; if you only have a name, call find_tasks first."},"taskName":{"type":"string","description":"Fallback when the id is unknown."},"person":{"type":"string","description":"Who, as the user named them, or an email address."},"level":{"type":"string","enum":["view","partner","assign"],"description":"Access level (default view)."}},"required":["person"]},"_surfaces":["text","voice"]},{"type":"function","name":"unshare_task","description":"Stop sharing a task with someone. If the task is shared with several people and person is omitted, the result lists them — ask which.","parameters":{"type":"object","properties":{"taskId":{"type":"string","description":"The task's id — from the context snapshot, get_tasks, find_tasks, or a task created this turn. Never guess an id; if you only have a name, call find_tasks first."},"person":{"type":"string","description":"Who, as the user named them."}},"required":["taskId"]},"_surfaces":["text","voice"]},{"type":"function","name":"open_screen","description":"Open a screen in the app for the user. Opening a screen is not an action on their data — never describe it as one.","parameters":{"type":"object","properties":{"screen":{"type":"string","enum":["today","tasks","calendar","day","week","month","focus","insights","lists","captures","settings","people","notifications","areas"],"description":"Which screen."},"id":{"type":"string","description":"A task or list id to open, when the screen shows one."}},"required":["screen"]},"_surfaces":["text","voice"]},{"type":"function","name":"request_call","description":"Book a phone call from Unstuck ONLY when the user asks for one (\"call me at 3 about James\"). Give when (a standalone time) OR taskId with leadMin (rings before that task's slot). Notes are read back VERBATIM when the call opens — one item each. Never book unasked; you may offer one.","parameters":{"type":"object","properties":{"when":{"type":"string","description":"Local 'YYYY-MM-DD HH:MM' — only when the user gave a time."},"taskId":{"type":"string","description":"Task to ring before (uses its next scheduled slot)."},"leadMin":{"type":"integer","description":"Minutes before the slot (default 15)."},"label":{"type":"string","description":"What the call is about, in a few words: \"speak to James\"."},"notes":{"type":"array","items":{"type":"string"},"description":"The user's reminders, verbatim, one per item."}},"required":["label"]},"_surfaces":["text","voice"]},{"type":"function","name":"update_call","description":"Change a booked call's notes, time, or label.","parameters":{"type":"object","properties":{"callId":{"type":"string","description":"Call id from get_calls / request_call."},"when":{"type":"string","description":"New local 'YYYY-MM-DD HH:MM'."},"label":{"type":"string","description":"New label."},"notes":{"type":"array","items":{"type":"string"},"description":"Replaces the notes, verbatim."}},"required":["callId"]},"_surfaces":["text","voice"]},{"type":"function","name":"cancel_call","description":"Cancel a booked call.","parameters":{"type":"object","properties":{"callId":{"type":"string","description":"Call id from get_calls."}},"required":["callId"]},"_surfaces":["text","voice"]},{"type":"function","name":"get_calls","description":"READ the calls booked from Unstuck, with their ids and times.","parameters":{"type":"object","properties":{},"required":[]},"_surfaces":["text","voice"]},{"type":"function","name":"snooze_call","description":"During a call from Unstuck only: hang up now and ring again in a few minutes.","parameters":{"type":"object","properties":{"minutes":{"type":"integer","description":"Minutes until the call comes back (default 10).","default":10}},"required":[]},"_surfaces":["call"]}]
"""#
    /// Parsed once. `voice` = the session's tools; `call` = call-mode extras.
    /// nonisolated(unsafe): `[[String: Any]]` isn't Sendable, but this is written once and never mutated.
    nonisolated(unsafe) static let all: [[String: Any]] = (try? JSONSerialization.jsonObject(with: Data(json.utf8))) as? [[String: Any]] ?? []
    static func tools(for surface: String) -> [[String: Any]] {
        all.filter { (($0["_surfaces"] as? [String]) ?? []).contains(surface) }.map { var t = $0; t.removeValue(forKey: "_surfaces"); return t }
    }
    static var voice: [[String: Any]] { tools(for: "voice") }
    static var call: [[String: Any]] { tools(for: "call") }
}
